INSERT INTO public.assessment_questions (framework, section_id, section_name, subsection, question_number, question, why_matters, regulatory_ref, risk, evidence_req, remediation, uid) VALUES
('popia', 8, 'South African Regulatory Context', 'Industry Codes of Conduct', 1, 'Is the organisation subject to an industry-specific code of conduct approved by the Information Regulator?', 'Industry-specific codes of conduct approved by the Information Regulator provide additional compliance requirements for specific sectors.', 'POPIA Chapter 7 codes of conduct; Information Regulator code approval process; relevant industry legislation', 'Medium', 'Code of conduct subscription; code compliance assessment; code implementation documentation; code review schedules; regulatory updates on codes.', 'Identify applicable industry codes of conduct. Subscribe to approved codes. Conduct compliance assessment against code requirements.', 'P8_SA_1'),
('popia', 8, 'South African Regulatory Context', 'Industry Codes of Conduct', 2, 'Does the organisation comply with all requirements of applicable industry codes?', 'Non-compliance with industry codes can result in regulatory action beyond POPIA.', 'POPIA Chapter 7 codes of conduct; Information Regulator code enforcement; industry-specific legislation', 'High', 'Code compliance assessment; gap identification; remediation plans; code audit records; regulatory correspondence.', 'Conduct comprehensive compliance assessment against applicable codes. Document gaps and implement remediation plans. Maintain records of regulatory correspondence.', 'P8_SA_2'),
('popia', 8, 'South African Regulatory Context', 'B-BBEE Compliance', 3, 'Are B-BBEE verification activities conducted in compliance with POPIA requirements?', 'B-BBEE verification requires processing of race and ethnic origin data, which is special personal information under POPIA.', 'POPIA Section 27 B-BBEE verification; B-BBEE Act requirements; Information Regulator guidance on special PI', 'High', 'B-BBEE verification procedures; special PI processing records; consent mechanisms; data minimisation for verification.', 'Implement POPIA-compliant B-BBEE verification procedures. Obtain consent for special PI processing. Apply data minimisation principles.', 'P8_SA_3'),
('popia', 8, 'South African Regulatory Context', 'Employment Equity', 4, 'Are Employment Equity data processing activities conducted in compliance with POPIA?', 'Employment Equity requires processing of race, gender, and disability data, which are special personal information under POPIA.', 'POPIA Section 26 special personal information; Employment Equity Act requirements; Information Regulator guidance on special PI', 'High', 'Employment Equity data processing procedures; special PI processing records; consent mechanisms; data minimisation for EE data.', 'Implement POPIA-compliant Employment Equity data processing. Obtain consent for special PI processing. Apply data minimisation principles.', 'P8_SA_4'),
('popia', 8, 'South African Regulatory Context', 'Information Regulator Interaction', 5, 'Has the organisation established procedures for interacting with the Information Regulator?', 'The Information Regulator is the primary regulatory authority for POPIA compliance. Organisations must know how to interact with the regulator effectively.', 'Information Regulator contact procedures; eServices portal usage; regulatory submission procedures; correspondence management; complaint handling procedures.', 'High', 'Information Regulator contact procedures; eServices portal account; regulatory submission templates; correspondence management system; complaint handling workflow.', 'Establish Information Regulator interaction procedures. Register for eServices portal. Develop submission templates and correspondence management system.', 'P8_SA_5'),
('popia', 8, 'South African Regulatory Context', 'Information Regulator Interaction', 6, 'Does the organisation maintain up-to-date knowledge of Information Regulator guidance and decisions?', 'The Information Regulator regularly issues guidance and decisions that affect compliance requirements.', 'Information Regulator guidance subscription; regulatory change monitoring; guidance review process; implementation of regulatory updates; training on regulatory changes.', 'Medium', 'Regulatory guidance subscription; guidance review schedule; regulatory change monitoring; implementation tracking for guidance updates; training on regulatory changes.', 'Subscribe to Information Regulator guidance. Implement regular review process. Track regulatory changes and update practices accordingly.', 'P8_SA_6'),
('popia', 8, 'South African Regulatory Context', 'PAIA Integration', 7, 'Is the POPIA compliance information properly integrated with the PAIA manual?', 'The PAIA manual must include POPIA processing information as required by the integration of POPIA and PAIA.', 'PAIA Section 51 POPIA integration; Information Regulator PAIA manual guidelines; PAIA manual review process', 'High', 'PAIA manual review for POPIA content; POPIA information mapping to PAIA categories; manual update procedures; integration documentation.', 'Review PAIA manual to ensure POPIA information is properly integrated. Map POPIA processing information to PAIA categories. Update manual when POPIA practices change.', 'P8_SA_7'),
('popia', 8, 'South African Regulatory Context', 'Automated Decision Making', 8, 'Are automated decision-making systems compliant with Section 71 requirements?', 'Section 71 regulates automated decision-making and requires specific safeguards and transparency requirements.', 'POPIA Section 71 automated decision making; ISO 27701 cl.7.3.3 automated decision making; Protection of Personal Information Act 4 of 2013', 'Critical', 'ADM system documentation; transparency documentation; appeal mechanisms; user testing of ADM systems; legal review of ADM compliance.', 'Document all ADM systems and their logic. Provide meaningful information about logic to data subjects. Implement appeal mechanisms. Conduct legal review.', 'P8_SA_8');